// LoadApprovedByUser loads the approval's ApprovedByUser into the .R struct
func (os ApprovalSlice) LoadApprovedByUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	users, err := os.ApprovedByUser(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.ApprovedByUser = nil
		o.R.Loaded.ApprovedByUser = true
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range users {
			if !o.ApprovedBy.Valid {
				continue
			}

			if !(o.ApprovedBy.Valid && o.ApprovedBy.V == rel.ID) {
				continue
			}

			o.R.ApprovedByUser = rel
			break
		}
	}

	return nil
}

