type approvalJoins[Q dialect.Joinable] struct {
	typ             string
	ApprovedByUser  modAs[Q, userColumns]
	RequestedByUser modAs[Q, userColumns]
	RunTaskRun      modAs[Q, taskRunColumns]
}

func (j approvalJoins[Q]) aliasedAs(alias string) approvalJoins[Q] {
	return buildApprovalJoins[Q](buildApprovalColumns(alias), j.typ)
}

func buildApprovalJoins[Q dialect.Joinable](cols approvalColumns, typ string) approvalJoins[Q] {
	return approvalJoins[Q]{
		typ: typ,
		ApprovedByUser: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.ApprovedBy),
					))
				}

				return mods
			},
		},
		RequestedByUser: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.RequestedBy),
					))
				}

				return mods
			},
		},
		RunTaskRun: modAs[Q, taskRunColumns]{
			c: TaskRuns.Columns,
			f: func(to taskRunColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, TaskRuns.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.RunID),
					))
				}

				return mods
			},
		},
	}
}
